#!/bin/sh
# Shrink a Tizen Studio tree to just what `tizen package -t wgt -s` needs, so the
# CI/Docker image stays small (~100 MB instead of ~2.4 GB). Run it right after the
# headless install (install-tizen-cli.sh), before the final image layer.
#
# KEPT (the packaging + signing tree, measured on a 5.0 install, ~93 MB):
#   sdk.info                         path config (regenerated by install-tizen-cli.sh)
#   library/sdk-utils-core.jar       referenced by tizen.sh classpath
#   tools/ide/bin/                   the `tizen` CLI launcher (tizen, tizen.sh)
#   tools/ide/lib-ncli/             CLI jars + libspawner.so + the sign jars
#                                     (org.tizen.common.sign, KeyCertGeneratorApi)
#   tools/ide/conf-ncli/            log4j / CLI config
#   tools/certificate-generator/    distributor signer p12s used by `-s` signing
#   tools/certificate-encryptor/    secret-tool (cert password handling)
#   platforms/tizen-5.0/            5.0 privileges/features/schemas the wgt validator reads
#   platforms/common/               shared schemas
# Java: NOT kept. tizen.sh falls back to system `java` (the image has
#   openjdk-17-jre-headless), logging "Using System java".
#
# NOT kept (web .wgt does not need them): jdk/, dl/, license/, ide/ (Eclipse),
#   package-manager/, tools/{emulator,sec-tv-simulator,tizen-doctor,gcovr,
#   device-manager,tizen-core}, platforms/* except 5.0 + common.
#
# NATIVE .tpk NOTE: the native path additionally needs a TV 5.0 *rootstrap*
# (absent from every known install) and tools/tizen-core (native templates/build).
# This slim set is web-.wgt-only on purpose; add those two back once a rootstrap
# is obtained. See install-tizen-cli.sh for the rootstrap gap.
set -e
DEST=${1:?usage: slim-tizen-cli.sh <tizen-studio-dir>}

before=$(du -sh "$DEST" 2>/dev/null | cut -f1)

rm -rf "$DEST"/jdk "$DEST"/dl "$DEST"/license "$DEST"/ide "$DEST"/package-manager
for d in emulator sec-tv-simulator tizen-doctor gcovr device-manager tizen-core; do
  rm -rf "$DEST/tools/$d"
done
# drop every platform except 5.0 + common
for p in "$DEST"/platforms/*; do
  case "${p##*/}" in tizen-5.0|common) : ;; *) rm -rf "$p" ;; esac
done

after=$(du -sh "$DEST" 2>/dev/null | cut -f1)
echo "[slim] tizen-studio: $before -> $after"

# self-check: the launcher + signing jar must survive
test -x "$DEST/tools/ide/bin/tizen" || { echo "[slim] FAIL: tizen CLI missing"; exit 1; }
ls "$DEST"/tools/ide/lib-ncli/org.tizen.common.sign_*.jar >/dev/null 2>&1 \
  || { echo "[slim] FAIL: sign jar missing"; exit 1; }
test -f "$DEST/tools/certificate-generator/certificates/distributor/tizen-distributor-signer.p12" \
  || { echo "[slim] FAIL: distributor signer missing"; exit 1; }
echo "[slim] ok (wgt packaging + signing tree intact)"
